    private Features() {
    }

    private static void newCategory(String name) {
        if (!CATEGORIES.contains(name)) CATEGORIES.add(name);
    }

    private static void add(String id, String category, String name) {
        Feature f = new Feature(id, category, name);
        ALL.add(f);
        BY_ID.put(id, f);
    }

    public static List<Feature> all() {
        return Collections.unmodifiableList(ALL);
    }

    public static List<String> categories() {
        return Collections.unmodifiableList(CATEGORIES);
    }

    public static Feature byId(String id) {
        return id == null ? null : BY_ID.get(id);
    }

    public static List<Feature> inCategory(String category) {
        List<Feature> out = new ArrayList<Feature>();
        for (Feature f : ALL) {
            if (f.category.equals(category)) out.add(f);
        }
        return out;
    }
